mode=${1:-menu}
case "$mode" in
    --help|-h) usage; exit 0 ;;
    --xray-info) shift; show_xray_info "$@"; exit 0 ;;
    --host-recover*)
        if [[ $mode != --host-recover || $# -ne 1 ]]; then
            printf '%s\n' '恢复命令不接受事务路径；不要附加冒号或其他内容。' '请单独执行：' '  rrv --host-recover' '也可打开 rrv，选择主菜单 12。本次没有执行恢复。' >&2
            exit 2
        fi
        mode=host-recover
        ;;
    --verify|menu|install|--install|--configure|--upgrade-core|--rebuild|--update-manager|--update-manager-and-defaults|--defaults-preview|--apply-defaults|--versions|--policy-status|--stats|--service-nice|--client|--status|--start|--stop|--logs|--micro-menu|--micro-28|--network|--cleanup-menu|--cleanup|--cleanup-preview|--host-status)
        [[ $# -le 1 ]] || { usage >&2; exit 2; }
        [[ $mode == --verify ]] || mode=${mode#--}
        ;;
    *) usage >&2; exit 2 ;;
esac

if [[ $mode != --verify ]]; then
    [[ ${EUID} -eq 0 ]] || { echo '请使用 root 执行安装。' >&2; exit 1; }
    [[ $(uname -s) == Linux && $(uname -m) == x86_64 ]] || { echo '需要 Linux x86_64。' >&2; exit 1; }
    # shellcheck source=/dev/null
    source /etc/os-release
    [[ ${ID:-} == debian && ( ${VERSION_ID:-} == 12 || ${VERSION_ID:-} == 13 ) ]] || { echo '此安装入口适用于 Debian 12 或 13。' >&2; exit 1; }
    command -v systemctl >/dev/null || { echo '需要 systemd/systemctl。' >&2; exit 1; }
fi

payload_tmp=$(mktemp -d)
trap 'rm -rf -- "$payload_tmp"' EXIT
payload_line=$(awk '/^__REALITY_SOURCE_PAYLOAD__$/ {print NR + 1; exit}' "${BASH_SOURCE[0]}")
[[ $payload_line =~ ^[0-9]+$ ]] || { echo '内嵌源码包缺失，请重新上传完整脚本。' >&2; exit 1; }
tail -n +"$payload_line" "${BASH_SOURCE[0]}" | base64 --decode > "$payload_tmp/source.zip"
if ! printf '%s  %s\n' '68561cafee8f435dc99a2417be4b959e7112540394e63cb4583ac88eab6e7942' "$payload_tmp/source.zip" | sha256sum --check --status; then
    echo '内嵌源码包校验失败，请重新下载并上传完整脚本。' >&2
    exit 1
fi
echo '内嵌源码包校验通过。'
[[ $mode == --verify ]] && exit 0

if ! command -v python3 >/dev/null; then
    apt-get update
    apt-get install -y --no-install-recommends python3
fi
work_base=${REALITY_LAB_WORKDIR:-/root/reality-rust-builds}
[[ $work_base == /* ]] || { echo 'REALITY_LAB_WORKDIR 必须为绝对路径。' >&2; exit 1; }
# Keep the caller's standard input available to input()/getpass in the manager.
# Executing `python3 - <<...` would make every child inherit an exhausted input.
cat > "$payload_tmp/unpack.py" <<'PY_REX12_UNPACK'
#!/usr/bin/env python3
"""Root-owned source extraction; held lock protects extraction and manager execution."""
import fcntl,hashlib,json,os,signal,stat,subprocess,sys,tempfile,zipfile
from pathlib import Path,PurePosixPath

def safe_directory(path):
    for part in reversed((path,*path.parents)):
        if part.exists() or part.is_symlink():
            st=part.lstat()
            if not stat.S_ISDIR(st.st_mode) or st.st_uid != os.geteuid():
                raise ValueError('构建目录包含符号链接、非目录或其他账户拥有的路径')
            if st.st_mode & 0o022 and not st.st_mode & stat.S_ISVTX:
                raise ValueError('构建目录的上级路径可被其他账户写入')
        else:part.mkdir(mode=0o700)

def run(archive,base,release,installer,action):
    base=Path(os.path.abspath(base));safe_directory(base)
    if base.stat().st_mode & 0o022:raise ValueError('构建目录不能由其他账户写入')
    lock=base/'.rex6-source.lock'
    fd=os.open(lock,os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
    try:
        st=os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_uid != os.geteuid() or st.st_mode & 0o022:raise ValueError('构建锁文件不安全')
        try:fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise ValueError('另一个 REX12 管理任务正在使用此目录') from None
        build=base/release;safe_directory(build)
        with zipfile.ZipFile(archive) as z:
            names=z.namelist()
            if len(names)!=len(set(names)):raise ValueError('源码包包含重名文件')
            manifest=json.loads(z.read('reality-vision-lab/MANIFEST.sha256.json'))
            expected={'reality-vision-lab/'+v for v in manifest}|{'reality-vision-lab/MANIFEST.sha256.json'}
            if set(names)!=expected or sum(i.file_size for i in z.infolist())>100*1024*1024:raise ValueError('源码包清单或大小无效')
            for info in z.infolist():
                rel=PurePosixPath(info.filename)
                if rel.is_absolute() or '..' in rel.parts or rel.parts[0]!='reality-vision-lab' or stat.S_ISLNK(info.external_attr>>16):raise ValueError('源码包路径无效')
                data=z.read(info)
                if str(rel)!='reality-vision-lab/MANIFEST.sha256.json' and hashlib.sha256(data).hexdigest()!=manifest[str(rel.relative_to('reality-vision-lab'))]:raise ValueError('源码包文件摘要无效')
                out=build/str(rel);safe_directory(out.parent)
                if out.is_symlink() or (out.exists() and not out.is_file()):raise ValueError('已有源码路径不是普通文件')
                mode=0o700 if (info.external_attr>>16)&0o111 else 0o600
                if out.exists() and out.read_bytes()==data:
                    os.chmod(out,mode);continue
                temp_fd,name=tempfile.mkstemp(prefix='.rex6-',dir=out.parent)
                try:
                    with os.fdopen(temp_fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
                    os.chmod(name,mode);os.replace(name,out)
                finally:
                    if os.path.exists(name):os.unlink(name)
        project=build/'reality-vision-lab'
        # Ctrl+C reaches the whole terminal group. Let the manager finish its own
        # rollback: subprocess.call otherwise kills it when the parent interrupts.
        # A caught handler resets on exec, so the child still receives SIGINT.
        previous=signal.signal(signal.SIGINT,lambda *_:None)
        try:
            status=subprocess.call([sys.executable,str(project/'scripts/manage.py'),'--project',str(project),'--installer-self',installer,'--action',action])
            return 128-status if status<0 else status
        finally:signal.signal(signal.SIGINT,previous)
    finally:os.close(fd)

if __name__=='__main__':
    try:raise SystemExit(run(*sys.argv[1:]))
    except KeyboardInterrupt:raise SystemExit(130)
    except (ValueError,OSError,zipfile.BadZipFile,KeyError):raise SystemExit('源码包解压/路径检查失败；检查私有构建目录权限、并发任务及文件完整性。')
PY_REX12_UNPACK
python3 "$payload_tmp/unpack.py" "$payload_tmp/source.zip" "$work_base" '0.5.1-68561cafee8f' "$(realpath -- "${BASH_SOURCE[0]}")" "$mode"
exit 0
__REALITY_SOURCE_PAYLOAD__
